DuneBan-Paper-1.0.0.jar.descriptor:
name: DuneBan
version: 1.0.0
main: com.dunerealms.ban.DuneBan
api-version: '1.21'
softdepend: [DuneCore, LuckPerms]
commands:
  duneban:
    description: Create an explicitly local or global ban
  duneunban:
    description: Remove an exact reviewed local or global ban
permissions:
  dune.ban.local: {default: op}
  dune.ban.global: {default: op}
  dune.unban.local: {default: op}
  dune.unban.global: {default: op}
  dune.ban.protected: {default: false}
